-- ============================================================
-- E-COMMERCE MANAGEMENT SYSTEM
-- 12 TABLES x 5,000 EXPLICIT RECORDS EACH = 60,000 RECORDS
-- ============================================================

CREATE DATABASE ecommerce_db_;
USE ecommerce_db_;

SET FOREIGN_KEY_CHECKS = 0;

CREATE TABLE customers (
    customer_id INT PRIMARY KEY AUTO_INCREMENT,
    customer_name VARCHAR(100) NOT NULL,
    email VARCHAR(100) UNIQUE,
    phone VARCHAR(15),
    gender VARCHAR(10),
    date_of_birth DATE,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE addresses (
    address_id INT PRIMARY KEY AUTO_INCREMENT,
    customer_id INT NOT NULL,
    address_line VARCHAR(150),
    city VARCHAR(50),
    state VARCHAR(50),
    pincode VARCHAR(10),
    address_type VARCHAR(20),
    FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
);

CREATE TABLE categories (
    category_id INT PRIMARY KEY AUTO_INCREMENT,
    category_name VARCHAR(100) NOT NULL UNIQUE,
    description VARCHAR(200)
);

CREATE TABLE brands (
    brand_id INT PRIMARY KEY AUTO_INCREMENT,
    brand_name VARCHAR(100) NOT NULL UNIQUE,
    country VARCHAR(50)
);

CREATE TABLE products (
    product_id INT PRIMARY KEY AUTO_INCREMENT,
    product_name VARCHAR(120) NOT NULL,
    category_id INT NOT NULL,
    brand_id INT NOT NULL,
    price DECIMAL(10,2),
    stock_quantity INT,
    product_description VARCHAR(255),
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (category_id) REFERENCES categories(category_id),
    FOREIGN KEY (brand_id) REFERENCES brands(brand_id)
);

CREATE TABLE suppliers (
    supplier_id INT PRIMARY KEY AUTO_INCREMENT,
    supplier_name VARCHAR(100) NOT NULL,
    contact_person VARCHAR(100),
    phone VARCHAR(15),
    email VARCHAR(100),
    city VARCHAR(50),
    state VARCHAR(50)
);

CREATE TABLE inventory (
    inventory_id INT PRIMARY KEY AUTO_INCREMENT,
    product_id INT NOT NULL,
    stock_quantity INT NOT NULL,
    reorder_level INT NOT NULL,
    last_restocked_date DATE,
    FOREIGN KEY (product_id) REFERENCES products(product_id)
);

CREATE TABLE orders (
    order_id INT PRIMARY KEY AUTO_INCREMENT,
    customer_id INT NOT NULL,
    order_date DATE,
    order_status VARCHAR(30),
    total_amount DECIMAL(10,2),
    FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
);

CREATE TABLE order_items (
    order_item_id INT PRIMARY KEY AUTO_INCREMENT,
    order_id INT NOT NULL,
    product_id INT NOT NULL,
    quantity INT NOT NULL,
    unit_price DECIMAL(10,2),
    FOREIGN KEY (order_id) REFERENCES orders(order_id),
    FOREIGN KEY (product_id) REFERENCES products(product_id)
);

CREATE TABLE payments (
    payment_id INT PRIMARY KEY AUTO_INCREMENT,
    order_id INT NOT NULL,
    payment_method VARCHAR(30),
    amount_paid DECIMAL(10,2),
    payment_date DATE,
    payment_status VARCHAR(20),
    FOREIGN KEY (order_id) REFERENCES orders(order_id)
);

CREATE TABLE shipments (
    shipment_id INT PRIMARY KEY AUTO_INCREMENT,
    order_id INT NOT NULL,
    tracking_number VARCHAR(50) UNIQUE,
    courier_name VARCHAR(50),
    shipping_address_id INT,
    shipped_date DATE,
    expected_delivery_date DATE,
    delivered_date DATE,
    shipment_status VARCHAR(30),
    FOREIGN KEY (order_id) REFERENCES orders(order_id),
    FOREIGN KEY (shipping_address_id) REFERENCES addresses(address_id)
);

CREATE TABLE reviews (
    review_id INT PRIMARY KEY AUTO_INCREMENT,
    customer_id INT NOT NULL,
    product_id INT NOT NULL,
    rating INT,
    review_text VARCHAR(500),
    review_date DATE,
    FOREIGN KEY (customer_id) REFERENCES customers(customer_id),
    FOREIGN KEY (product_id) REFERENCES products(product_id)
);

SET FOREIGN_KEY_CHECKS = 1;

-- 1. CUSTOMERS - 5,000 records

-- 2. ADDRESSES - 5,000 records

-- 3. CATEGORIES - 5,000 records

-- 4. BRANDS - 5,000 records

-- 5. PRODUCTS - 5,000 records

-- 6. SUPPLIERS - 5,000 records

-- 7. INVENTORY - 5,000 records

-- 8. ORDERS - 5,000 records

-- 9. ORDER ITEMS - 5,000 records

-- 10. PAYMENTS - 5,000 records

-- 11. SHIPMENTS - 5,000 records

-- 12. REVIEWS - 5,000 records

-- ============================================================
-- VERIFY: EVERY TABLE SHOULD SHOW 5,000
-- ============================================================

SELECT 'customers' AS table_name, COUNT(*) AS total_records FROM customers
UNION ALL SELECT 'addresses', COUNT(*) FROM addresses
UNION ALL SELECT 'categories', COUNT(*) FROM categories
UNION ALL SELECT 'brands', COUNT(*) FROM brands
UNION ALL SELECT 'products', COUNT(*) FROM products
UNION ALL SELECT 'suppliers', COUNT(*) FROM suppliers
UNION ALL SELECT 'inventory', COUNT(*) FROM inventory
UNION ALL SELECT 'orders', COUNT(*) FROM orders
UNION ALL SELECT 'order_items', COUNT(*) FROM order_items
UNION ALL SELECT 'payments', COUNT(*) FROM payments
UNION ALL SELECT 'shipments', COUNT(*) FROM shipments
UNION ALL SELECT 'reviews', COUNT(*) FROM reviews;

SELECT
    (SELECT COUNT(*) FROM customers) +
    (SELECT COUNT(*) FROM addresses) +
    (SELECT COUNT(*) FROM categories) +
    (SELECT COUNT(*) FROM brands) +
    (SELECT COUNT(*) FROM products) +
    (SELECT COUNT(*) FROM suppliers) +
    (SELECT COUNT(*) FROM inventory) +
    (SELECT COUNT(*) FROM orders) +
    (SELECT COUNT(*) FROM order_items) +
    (SELECT COUNT(*) FROM payments) +
    (SELECT COUNT(*) FROM shipments) +
    (SELECT COUNT(*) FROM reviews) AS total_project_records;
    
select * from customers
select * from addresses

desc payments

-- 1.Find the top 10 customers based on their total spending.
select a.customer_id, a.customer_name, b.order_id, c.amount_paid
from customers as a 
inner join orders as b on a.customer_id = b.customer_id
inner join payments as c on c.order_id = b.order_id 
order by c.amount_paid desc limit 10

-- 2.Find customers whose total spending is greater than the average spending of all customers.
select a.customer_id, a.customer_name, sum(b.amount_paid) as total_spend
from customers as a
inner join orders as c on a.customer_id = c.customer_id 
inner join payments as b on b.order_id = c.order_id 
group by a.customer_id, a.customer_name 
having sum(b.amount_paid) > (
select avg(customer_total)
from (
select c.customer_id, sum(b.amount_paid) as customer_total
from orders as c 
inner join payments as b on c.order_id = b.order_id 
group by c.customer_id
) as customer_spending
)
order by total_spend desc

-- 3.Find the top 10 products based on total quantity sold.
desc order_items
select * from products select * from orders
select a.customer_name, b.product_id, b.product_name, d.quantity
from customers as a 
inner join orders as c on c.customer_id = a.customer_id
inner join order_items as d on c.order_id = d.order_id
inner join products as b on b.product_id=d.product_id
order by d.quantity desc limit 10

-- 4.Find the top 10 products generating the highest revenue.
select a.product_id, a.product_name, sum(b.quantity) as total_quantity,
sum(b.quantity * b.unit_price) as total_revenue
from products as a 
inner join order_items as b on a.product_id = b.product_id
group by a.product_id, a.product_name
order by total_revenue desc limit 10

-- 5.For every category, find: category_name, number_of_products,
-- average_product_price, total_quantity_sold, total_revenue
-- Sort by total revenue descending.

select * from products

select a.category_id, a.category_name, count(distinct b.product_id) as 
no_of_product, avg(distinct b.price) as average_pro_price, 
sum(c.quantity) as total_quantity, 
sum(c.quantity * c.unit_price) as total_revenue 
from categories as a 
left join products as b on b.category_id = a.category_id
left join order_items as c on c.product_id = b.product_id
group by a.category_id, a.category_name
order by total_revenue desc
limit 10

-- 6. Find customers who have placed more than 5 orders.
SELECT 
    a.customer_id,
    a.customer_name,
    COUNT(b.order_id) AS total_orders
FROM customers AS a
INNER JOIN orders AS b
    ON a.customer_id = b.customer_id
GROUP BY a.customer_id, a.customer_name
HAVING COUNT(b.order_id) > 5
ORDER BY total_orders DESC;

-- 7. Find products that have never been ordered.
SELECT 
    a.product_id,
    a.product_name,
    a.price
FROM products AS a
LEFT JOIN order_items AS b
    ON a.product_id = b.product_id
WHERE b.product_id IS NULL;

-- 8. Find the customer who placed the highest-value single order.
SELECT 
    a.customer_id,
    a.customer_name,
    b.order_id,
    b.total_amount
FROM customers AS a
INNER JOIN orders AS b
    ON a.customer_id = b.customer_id
ORDER BY b.total_amount DESC
LIMIT 1;

-- 9. Find the top 5 brands based on total revenue.
SELECT 
    a.brand_id,
    a.brand_name,
    SUM(c.quantity * c.unit_price) AS total_revenue
FROM brands AS a
INNER JOIN products AS b
    ON a.brand_id = b.brand_id
INNER JOIN order_items AS c
    ON b.product_id = c.product_id
GROUP BY a.brand_id, a.brand_name
ORDER BY total_revenue DESC
LIMIT 5;

-- 10. Find the highest-selling product in each category.
SELECT 
    category_name,
    product_name,
    total_quantity
FROM
(
    SELECT 
        a.category_name,
        b.product_name,
        SUM(c.quantity) AS total_quantity,
        RANK() OVER (
            PARTITION BY a.category_id
            ORDER BY SUM(c.quantity) DESC
        ) AS product_rank
    FROM categories AS a
    INNER JOIN products AS b
        ON a.category_id = b.category_id
    INNER JOIN order_items AS c
        ON b.product_id = c.product_id
    GROUP BY 
        a.category_id,
        a.category_name,
        b.product_id,
        b.product_name
) AS x
WHERE product_rank = 1;

-- 11. Find customers who have placed orders in every month of a year.
SELECT
    c.customer_id,
    c.customer_name,
    COUNT(DISTINCT MONTH(o.order_date)) AS active_months
FROM customers AS c
INNER JOIN orders AS o
    ON c.customer_id = o.customer_id
WHERE YEAR(o.order_date) = 2025
GROUP BY c.customer_id, c.customer_name
HAVING COUNT(DISTINCT MONTH(o.order_date)) = 12;

--12. Find the second-highest-priced product in each category. 
WITH ProductRanking AS (
    SELECT
        c.category_name,
        p.product_id,
        p.product_name,
        p.price,
        DENSE_RANK() OVER (
            PARTITION BY p.category_id
            ORDER BY p.price DESC
        ) AS price_rank
    FROM products AS p
    INNER JOIN categories AS c
        ON p.category_id = c.category_id
)
SELECT
    category_name,
    product_id,
    product_name,
    price
FROM ProductRanking
WHERE price_rank = 2;

-- 13. Classify products based on their stock availability.
SELECT
    product_id,
    product_name,
    stock_quantity,
    reorder_level,
    CASE
        WHEN stock_quantity = 0 THEN 'Out of Stock'
        WHEN stock_quantity <= reorder_level THEN 'Low Stock'
        WHEN stock_quantity <= reorder_level * 2 THEN 'Medium Stock'
        ELSE 'High Stock'
    END AS stock_status
FROM products
ORDER BY stock_quantity ASC;

-- 14. Find each customer's previous order date and the number of days since that order.
WITH CustomerOrders AS (
    SELECT
        customer_id,
        order_id,
        order_date,
        LAG(order_date) OVER (
            PARTITION BY customer_id
            ORDER BY order_date
        ) AS previous_order_date
    FROM orders
)
SELECT
    customer_id,
    order_id,
    order_date,
    previous_order_date,
    DATEDIFF(
        order_date,
        previous_order_date
    ) AS days_between_orders
FROM CustomerOrders
ORDER BY customer_id, order_date;

-- 15. Find duplicate customer email addresses.
SELECT
    email,
    COUNT(*) AS duplicate_count
FROM customers
WHERE email IS NOT NULL
GROUP BY email
HAVING COUNT(*) > 1
ORDER BY duplicate_count DESC;